CREATE TABLE "${primehrSchema}".succession_readiness_assessment (
 id VARCHAR(36) PRIMARY KEY, agency_id VARCHAR(64) NOT NULL, candidate_id VARCHAR(36) NOT NULL, cycle_id VARCHAR(36) NOT NULL, charter_version_id VARCHAR(36) NOT NULL, readiness_scale_version_id VARCHAR(36) NOT NULL, readiness_scale_definition_version INTEGER NOT NULL, position_profile_id VARCHAR(36) NOT NULL, position_profile_definition_version INTEGER NOT NULL, position_profile_content_revision BIGINT NOT NULL, position_profile_fingerprint VARCHAR(120) NOT NULL, person_profile_id VARCHAR(36) NOT NULL, person_profile_version INTEGER NOT NULL, gap_calculated_at TIMESTAMP WITH TIME ZONE NOT NULL, below_count INTEGER NOT NULL, meets_count INTEGER NOT NULL, exceeds_count INTEGER NOT NULL, not_assessed_count INTEGER NOT NULL, status VARCHAR(20) NOT NULL, recommended_level_id VARCHAR(36), recommended_level_code VARCHAR(80), recommended_level_label VARCHAR(200), pool_recommended BOOLEAN, recommendation_narrative VARCHAR(4000), recommended_by VARCHAR(100), recommended_at TIMESTAMP WITH TIME ZONE, finalized_by VARCHAR(100), finalized_at TIMESTAMP WITH TIME ZONE, record_version BIGINT NOT NULL DEFAULT 0, created_by VARCHAR(100) NOT NULL, created_at TIMESTAMP WITH TIME ZONE NOT NULL, updated_by VARCHAR(100) NOT NULL, updated_at TIMESTAMP WITH TIME ZONE NOT NULL,
 CONSTRAINT uk_succ_readiness_candidate UNIQUE(agency_id,candidate_id), CONSTRAINT fk_succ_ready_candidate FOREIGN KEY(candidate_id) REFERENCES "${primehrSchema}".succession_candidate(id), CONSTRAINT fk_succ_ready_cycle FOREIGN KEY(cycle_id) REFERENCES "${primehrSchema}".succession_cycle(id), CONSTRAINT fk_succ_ready_charter FOREIGN KEY(charter_version_id) REFERENCES "${primehrSchema}".succession_committee_charter_version(id), CONSTRAINT fk_succ_ready_scale FOREIGN KEY(readiness_scale_version_id) REFERENCES "${primehrSchema}".succession_readiness_scale_version(id), CONSTRAINT fk_succ_ready_position_profile FOREIGN KEY(position_profile_id) REFERENCES "${primehrSchema}".prime_position_profile(id), CONSTRAINT fk_succ_ready_person_profile FOREIGN KEY(person_profile_id) REFERENCES "${primehrSchema}".prime_person_competency_profile(id), CONSTRAINT ck_succ_ready_counts CHECK(below_count>=0 AND meets_count>=0 AND exceeds_count>=0 AND not_assessed_count>=0), CONSTRAINT ck_succ_ready_status CHECK(status IN('PANEL_REVIEW','RECOMMENDED','FINALIZED'))
);
CREATE INDEX ix_succ_ready_cycle_status ON "${primehrSchema}".succession_readiness_assessment(agency_id,cycle_id,status);

CREATE TABLE "${primehrSchema}".succession_readiness_gap_item (
 id VARCHAR(36) PRIMARY KEY, agency_id VARCHAR(64) NOT NULL, assessment_id VARCHAR(36) NOT NULL, position_requirement_id VARCHAR(36) NOT NULL, competency_version_id VARCHAR(36) NOT NULL, competency_code VARCHAR(80) NOT NULL, competency_name VARCHAR(200) NOT NULL, competency_definition_version INTEGER NOT NULL, scale_version_id VARCHAR(36) NOT NULL, scale_definition_version INTEGER NOT NULL, required_level_id VARCHAR(36) NOT NULL, required_level_code VARCHAR(80) NOT NULL, required_level_label VARCHAR(200) NOT NULL, required_level_order INTEGER NOT NULL, attained_level_id VARCHAR(36), attained_level_code VARCHAR(80), attained_level_label VARCHAR(200), attained_level_order INTEGER, gap_value INTEGER, gap_classification VARCHAR(30) NOT NULL, not_assessed_reason VARCHAR(40), requirement_classification VARCHAR(30) NOT NULL, criticality_code VARCHAR(80), display_order INTEGER NOT NULL, record_version BIGINT NOT NULL DEFAULT 0, created_by VARCHAR(100) NOT NULL, created_at TIMESTAMP WITH TIME ZONE NOT NULL, updated_by VARCHAR(100) NOT NULL, updated_at TIMESTAMP WITH TIME ZONE NOT NULL,
 CONSTRAINT uk_succ_readiness_gap_competency UNIQUE(agency_id,assessment_id,competency_version_id), CONSTRAINT fk_succ_ready_gap_assessment FOREIGN KEY(assessment_id) REFERENCES "${primehrSchema}".succession_readiness_assessment(id), CONSTRAINT ck_succ_ready_gap_class CHECK(gap_classification IN('BELOW','MEETS','EXCEEDS','NOT_ASSESSED')), CONSTRAINT ck_succ_ready_gap_order CHECK(display_order>=1)
);
CREATE INDEX ix_succ_ready_gap_assessment ON "${primehrSchema}".succession_readiness_gap_item(agency_id,assessment_id,display_order);

CREATE TABLE "${primehrSchema}".succession_readiness_panel_assignment (
 id VARCHAR(36) PRIMARY KEY, agency_id VARCHAR(64) NOT NULL, assessment_id VARCHAR(36) NOT NULL, committee_member_id VARCHAR(36) NOT NULL, employee_no VARCHAR(100) NOT NULL, display_name VARCHAR(250) NOT NULL, member_role VARCHAR(30) NOT NULL, voting_member BOOLEAN NOT NULL, status VARCHAR(20) NOT NULL, conflict_declared BOOLEAN NOT NULL, conflict_source VARCHAR(30), conflict_reason VARCHAR(2000), replacement_assignment_id VARCHAR(36), record_version BIGINT NOT NULL DEFAULT 0, created_by VARCHAR(100) NOT NULL, created_at TIMESTAMP WITH TIME ZONE NOT NULL, updated_by VARCHAR(100) NOT NULL, updated_at TIMESTAMP WITH TIME ZONE NOT NULL,
 CONSTRAINT uk_succ_readiness_panel_member UNIQUE(agency_id,assessment_id,employee_no), CONSTRAINT fk_succ_ready_panel_assessment FOREIGN KEY(assessment_id) REFERENCES "${primehrSchema}".succession_readiness_assessment(id), CONSTRAINT fk_succ_ready_panel_member FOREIGN KEY(committee_member_id) REFERENCES "${primehrSchema}".succession_committee_member(id), CONSTRAINT fk_succ_ready_panel_replacement FOREIGN KEY(replacement_assignment_id) REFERENCES "${primehrSchema}".succession_readiness_panel_assignment(id), CONSTRAINT ck_succ_ready_panel_status CHECK(status IN('ASSIGNED','RECUSED','REPLACED'))
);
CREATE INDEX ix_succ_ready_panel_actor ON "${primehrSchema}".succession_readiness_panel_assignment(agency_id,employee_no,status);

CREATE TABLE "${primehrSchema}".succession_readiness_criterion_finding (
 id VARCHAR(36) PRIMARY KEY, agency_id VARCHAR(64) NOT NULL, assessment_id VARCHAR(36) NOT NULL, criterion_code VARCHAR(80) NOT NULL, normalized_criterion_code VARCHAR(80) NOT NULL, criterion_label VARCHAR(200) NOT NULL, outcome VARCHAR(30) NOT NULL, rationale VARCHAR(4000) NOT NULL, source_reference VARCHAR(500) NOT NULL, employee_visible BOOLEAN NOT NULL, display_order INTEGER NOT NULL, record_version BIGINT NOT NULL DEFAULT 0, created_by VARCHAR(100) NOT NULL, created_at TIMESTAMP WITH TIME ZONE NOT NULL, updated_by VARCHAR(100) NOT NULL, updated_at TIMESTAMP WITH TIME ZONE NOT NULL,
 CONSTRAINT uk_succ_readiness_criterion UNIQUE(agency_id,assessment_id,normalized_criterion_code), CONSTRAINT fk_succ_ready_finding_assessment FOREIGN KEY(assessment_id) REFERENCES "${primehrSchema}".succession_readiness_assessment(id), CONSTRAINT ck_succ_ready_finding_outcome CHECK(outcome IN('MET','PARTIALLY_MET','NOT_MET','NEEDS_EVIDENCE')), CONSTRAINT ck_succ_ready_finding_order CHECK(display_order>=1)
);
CREATE INDEX ix_succ_ready_finding_assessment ON "${primehrSchema}".succession_readiness_criterion_finding(agency_id,assessment_id,display_order);

CREATE TABLE "${primehrSchema}".succession_pool_decision (
 id VARCHAR(36) PRIMARY KEY, agency_id VARCHAR(64) NOT NULL, assessment_id VARCHAR(36) NOT NULL, candidate_id VARCHAR(36) NOT NULL, outcome VARCHAR(20) NOT NULL, readiness_level_id VARCHAR(36) NOT NULL, readiness_level_code VARCHAR(80) NOT NULL, readiness_level_label VARCHAR(200) NOT NULL, employee_visible_reason VARCHAR(4000) NOT NULL, restricted_rationale VARCHAR(4000) NOT NULL, decided_by VARCHAR(100) NOT NULL, decided_at TIMESTAMP WITH TIME ZONE NOT NULL, effective_from DATE, expires_on DATE, record_version BIGINT NOT NULL DEFAULT 0, created_by VARCHAR(100) NOT NULL, created_at TIMESTAMP WITH TIME ZONE NOT NULL, updated_by VARCHAR(100) NOT NULL, updated_at TIMESTAMP WITH TIME ZONE NOT NULL,
 CONSTRAINT uk_succ_pool_decision_assessment UNIQUE(agency_id,assessment_id), CONSTRAINT fk_succ_pool_assessment FOREIGN KEY(assessment_id) REFERENCES "${primehrSchema}".succession_readiness_assessment(id), CONSTRAINT fk_succ_pool_candidate FOREIGN KEY(candidate_id) REFERENCES "${primehrSchema}".succession_candidate(id), CONSTRAINT fk_succ_pool_level FOREIGN KEY(readiness_level_id) REFERENCES "${primehrSchema}".succession_readiness_level(id), CONSTRAINT ck_succ_pool_outcome CHECK(outcome IN('INCLUDED','NOT_INCLUDED')), CONSTRAINT ck_succ_pool_dates CHECK((outcome='NOT_INCLUDED' AND effective_from IS NULL AND expires_on IS NULL) OR (outcome='INCLUDED' AND effective_from IS NOT NULL AND expires_on>=effective_from))
);
CREATE INDEX ix_succ_pool_candidate ON "${primehrSchema}".succession_pool_decision(agency_id,candidate_id,outcome);

